<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { feedbackApi } from '@/api'
const rows=ref<any[]>([]);const loading=ref(false);const page=ref(1);const total=ref(0);const filters=reactive({status:'',rating:''})
const statusText:Record<string,string>={PENDING:'待处理',PROCESSED:'已处理',IGNORED:'已忽略'}
const statusType:Record<string,'warning'|'success'|'info'|'primary'|'danger'|''>={PENDING:'warning',PROCESSED:'success',IGNORED:'info'}
async function load(){loading.value=true;try{const r=await feedbackApi.list({...filters,page:page.value,page_size:20});rows.value=r.data.data.list;total.value=r.data.pagination?.total||0}catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}}
async function handle(row:any,status:string){try{await ElMessageBox.confirm(`确定将该反馈标记为“${statusText[status]}”吗？`,'反馈处理',{type:'warning'});await feedbackApi.handle(row.feedback_id,{status});ElMessage.success('反馈状态已更新');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'操作失败')}}
onMounted(load)
</script>
<template><div class="panel page-stack"><div class="panel-head"><div><h3>用户反馈</h3><p>状态会持久化保存，刷新页面后仍保留处理结果</p></div><div class="filter-bar"><el-select v-model="filters.rating" placeholder="全部评价" clearable><el-option label="点赞" value="LIKE"/><el-option label="点踩" value="DISLIKE"/></el-select><el-select v-model="filters.status" placeholder="全部状态" clearable><el-option label="待处理" value="PENDING"/><el-option label="已处理" value="PROCESSED"/><el-option label="已忽略" value="IGNORED"/></el-select><el-button type="primary" @click="page=1;load()">筛选</el-button><el-button @click="load">刷新</el-button></div></div><el-table v-loading="loading" :data="rows" stripe><el-table-column label="评价" width="90"><template #default="{row}"><el-tag :type="row.rating==='LIKE'?'success':'danger'">{{row.rating==='LIKE'?'点赞':'点踩'}}</el-tag></template></el-table-column><el-table-column prop="username" label="用户" width="120"/><el-table-column prop="answer" label="被评价回答" min-width="280" show-overflow-tooltip/><el-table-column prop="reason" label="用户反馈" min-width="170" show-overflow-tooltip/><el-table-column label="处理状态" width="110"><template #default="{row}"><el-tag :type="statusType[row.status]">{{statusText[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column prop="handled_at" label="处理时间" width="180"/><el-table-column prop="created_at" label="提交时间" width="180"/><el-table-column label="操作" width="180"><template #default="{row}"><template v-if="row.status==='PENDING'"><el-button link type="success" @click="handle(row,'PROCESSED')">处理</el-button><el-button link type="info" @click="handle(row,'IGNORED')">忽略</el-button></template><span v-else class="muted">已记录</span></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="page" layout="prev, pager, next" :page-size="20" :total="total" @current-change="load"/></div></div></template>
